@pytest.mark.parametrize(
    "arguments, assertions",
    [
        (
            "a_string=4",
            {
                "expected_status": 1,
                "expected_outputs": [
                    'Argument of type "Literal[4]" cannot be assigned to parameter "a_string" of type "str | None"'
                ],
            },
        ),
        (
            "a_string='FooBar'",
            {
                "expected_status": 0,
            },
        ),
        (
            "a_number=''",
            {
                "expected_status": 1,
                "expected_outputs": [
                    'Argument of type "Literal[\'\']" cannot be assigned to parameter "a_number" ',
                    '"__float__" is not present',
                    '"__int__" is not present',
                    '"__complex__" is not present',
                ],
            },
        ),
        (
            "a_number=0",
            {
                "expected_status": 0,
            },
        ),
        (
            "a_number=2.2",
            {
                "expected_status": 0,
            },
        ),
        (
            "a_bool=4",
            {
                "expected_status": 1,
            },
        ),
        (
            "a_bool=True",
            {
                "expected_status": 0,
            },
        ),
        (
            "array_string={}",
            {
                "expected_status": 1,
                "expected_outputs": [
                    'Argument of type "dict[Any, Any]" cannot be assigned to parameter "array_string" '
                    'of type "Sequence[str] | None"'
                ],
            },
        ),
        (
            "array_string=[]",
            {
                "expected_status": 0,
            },
        ),
        (
            "array_string=[1,2,4]",
            {
                "expected_status": 1,
            },
        ),
        (
            "array_number=[1,2]",
            {
                "expected_status": 0,
            },
        ),
        (
            "array_number=['not','a', 'number']",
            {
                "expected_status": 1,
            },
        ),
        (
            "array_obj=[{'a': 'b'}]",
            {
                "expected_status": 0,
            },
        ),
        (
            "array_obj=[1]",
            {
                "expected_status": 1,
            },
        ),
        (
            "array_obj=[1, {}]",
            {
                "expected_status": 1,
            },
        ),
        (
            "union='Union'",
            {
                "expected_status": 0,
            },
        ),
        (
            "union=1",
            {
                "expected_status": 0,
            },
        ),
        (
            "union=0.42",
            {
                "expected_status": 0,
            },
        ),
        (
            "union=[]",
            {
                "expected_status": 1,
            },
        ),
        (
            "element=[]",
            {
                "expected_status": 0,
            },
        ),
        (
            "element=[TypeScriptComponent()]",
            {
                "expected_status": 0,
            },
        ),
        (
            "element=TypeScriptComponent()",
            {
                "expected_status": 0,
            },
        ),
        pytest.param(
            "element=set()",
            {
                "expected_status": 1,
            },
            marks=pytest.mark.skip(reason="Ignoring element=set() test case"),
        ),
        (
            "a_tuple=(1,2)",
            {
                "expected_status": 1,
                "expected_outputs": [
                    'Argument of type "tuple[Literal[1], Literal[2]]" cannot be assigned '
                    'to parameter "a_tuple" of type "Tuple[NumberType, str] | None'
                ],
            },
        ),
        (
            "a_tuple=(1, 'tuple')",
            {
                "expected_status": 0,
            },
        ),
        (
            "obj=set()",
            {
                "expected_status": 1,
            },
        ),
        (
            "obj={}",
            {
                "expected_status": 1,
                "expected_outputs": [
                    '"dict[Any, Any]" cannot be assigned to parameter "obj" of type "Obj | None"'
                ],
            },
        ),
        (
            "obj={'value': 'a', 'label': 1}",
            {
                "expected_status": 1,
                "expected_outputs": [
                    '"dict[str, str | int]" cannot be assigned to parameter "obj" of type "Obj | None"'
                ],
            },
        ),
        (
            "obj={'value': 'a', 'label': 'lab'}",
            {
                "expected_status": 0,
            },
        ),
    ],
)

